def solve(inp):
    h,w=len(inp),len(inp[0])
    g=[row[:] for row in inp]
    colored=[(r,c,inp[r][c]) for r in range(h) for c in range(w) if inp[r][c] not in (0,3)]
    empties=[(r,c) for r in range(1,h-1) for c in range(1,w-1)
             if inp[r][c]==0 and inp[r-1][c]==3 and inp[r+1][c]==3 and inp[r][c-1]==3 and inp[r][c+1]==3]
    def paint(cells,color,dirs):
        for r,c in cells:
            for dr,dc in dirs:
                rr,cc=r+dr,c+dc
                first=True
                while 0<=rr<h and 0<=cc<w:
                    if inp[rr][cc]==3:
                        if first: first=False; rr+=dr; cc+=dc; continue
                        break
                    g[rr][cc]=color
                    rr+=dr; cc+=dc
    H,V=[(0,1),(0,-1)],[(1,0),(-1,0)]
    for r,c,v in colored: paint([(r,c)],v,H)
    for r,c in empties:   paint([(r,c)],0,H)
    for r,c,v in colored: paint([(r,c)],v,V)
    for r,c in empties:   paint([(r,c)],0,V)
    return g
